/bin/bash -lc "node -e '
const fs = require(\"fs\");
const x = JSON.parse(fs.readFileSync(\"result.json\", \"utf8\"));
const same = (a,b) => JSON.stringify([...a].sort()) === JSON.stringify([...b].sort());
if ("'!same(Object.keys(x), ["total_cents","order_count","duplicates_skipped","by_region"])) throw Error("top-level keys");
if (!same(Object.keys(x.by_region), ["north","south","east","west"])) throw Error("region keys");
const values = [x.total_cents,x.order_count,x.duplicates_skipped,...Object.values(x.by_region)];
if (!values.every(Number.isInteger)) throw Error("non-integer value");
if (Object.values(x.by_region).reduce((a,b)=>a+b,0) !== x.total_cents) throw Error("region sum mismatch");
console.log("result.json valid; exact keys, integer values, and region sum verified");
'"'"

